<div class="suite-heading mb-3"><h4 class="m-0">Access Roles</h4><a class="btn btn-sm btn-outline-secondary" href="<?php echo $suiteEscape($suiteUrl) ?>"><i class="fas fa-plus mr-1"></i> New Role</a></div>
<div class="suite-role-layout"><section><h5><?php echo $selected?'Edit Role':'New Role' ?></h5><form class="suite-form" data-action="save_role" data-redirect="<?php echo $suiteEscape($suiteUrl) ?>"><input type="hidden" name="id" value="<?php echo $selected['id']??'' ?>"><input type="hidden" name="version" value="<?php echo $selected['version']??'' ?>"><div class="form-group"><label for="role-name">Role Name</label><input class="form-control form-control-sm" id="role-name" name="name" maxlength="100" required value="<?php echo $suiteEscape($selected['name']??'') ?>"></div><div class="form-group"><label for="role-description">Description</label><input class="form-control form-control-sm" id="role-description" name="description" maxlength="500" value="<?php echo $suiteEscape($selected['description']??'') ?>"></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Module</th><th>Access</th></tr></thead><tbody><?php foreach(App\Enterprise\WorkspaceService::SCOPES as $scope): ?><tr><td><?php echo ucfirst($scope) ?></td><td><select class="form-control form-control-sm" aria-label="<?php echo ucfirst($scope) ?> access" name="permissions[<?php echo $scope ?>]"><?php foreach(['none'=>'No Access','read'=>'Read','write'=>'Read & Write'] as $level=>$name): ?><option value="<?php echo $level ?>" <?php echo ($permissions[$scope]??'none')===$level?'selected':'' ?>><?php echo $name ?></option><?php endforeach ?></select></td></tr><?php endforeach ?></tbody></table></div><div class="suite-actions"><label class="m-0"><input name="active" type="checkbox" value="1" <?php echo ($selected['active']??1)?'checked':'' ?>> Active</label><button class="btn btn-primary btn-sm" type="submit"><i class="fas fa-save mr-1"></i> Save Role</button></div></form></section><section><h5>Roles</h5><div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($roles as $role): ?><tr><td><a href="<?php echo $suiteEscape($suiteUrl) ?>&id=<?php echo $role['id'] ?>"><?php echo $suiteEscape($role['name']) ?></a></td><td><?php echo $role['active']?'Active':'Inactive' ?></td></tr><?php endforeach ?></tbody></table></div><h5 class="mt-4">Staff Assignments</h5><?php foreach($suiteWorkspace->assignments() as $assignment): ?><form class="suite-form suite-assignment" data-action="assign_role"><input name="user_id" type="hidden" value="<?php echo $assignment['id'] ?>"><label class="mb-0" for="assignment-<?php echo $assignment['id'] ?>"><?php echo $suiteEscape($assignment['username']) ?></label><?php if((int)$assignment['type']===1): ?><span class="text-muted small">Administrator</span><?php else: ?><select class="form-control form-control-sm" id="assignment-<?php echo $assignment['id'] ?>" name="role_id"><option value="">Default Staff Access</option><?php echo $suiteSelect(array_values(array_filter($roles,static fn($row)=>(bool)$row['active'])),'id','name',$assignment['role_id']) ?></select><button class="btn btn-outline-primary btn-sm" title="Save assignment" aria-label="Save assignment" type="submit"><i class="fas fa-save"></i></button><?php endif ?></form><?php endforeach ?></section></div></div>
